export namespace FlowLogicSysId {
    export function getLogicId(logic: FLOW_LOGIC): string | undefined {
        return FLOW_LOGIC_SYS_ID_MAP[logic]
    }

    export function getLogicName(logicId: string): FLOW_LOGIC | undefined {
        return (Object.keys(FLOW_LOGIC_SYS_ID_MAP) as FLOW_LOGIC[]).find(
            (key) => FLOW_LOGIC_SYS_ID_MAP[key] === logicId
        )
    }
}

